<script setup lang="ts">import { onMounted, ref } from 'vue'; import axios from 'axios'; import api from '../plugins/axios'; const usuarios=ref<any[]>([]); const error=ref(''); async function cargar(){try{usuarios.value=(await api.get('/usuarios')).data}catch(e){error.value=axios.isAxiosError(e)?e.response?.data?.message??'No se pudieron cargar los clientes.':'No se pudieron cargar los clientes.'}} async function accion(id:number, tipo:string){const motivo=prompt('Motivo de la acción:');if(!motivo)return;try{await api.post(`/usuarios/${id}/${tipo}`,{motivo});await cargar()}catch(e){error.value=axios.isAxiosError(e)?e.response?.data?.message??'No se pudo completar la acción.':'No se pudo completar la acción.'}} onMounted(cargar)</script>
<template><section class="container py-5"><h1 class="h2 fw-bold mb-4">Clientes y usuarios</h1><div v-if="error" class="alert alert-danger">{{ error }}</div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Nombre</th><th>Celular</th><th>Rol</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="usuario in usuarios" :key="usuario.idUsuario"><td>{{ usuario.nombreCompleto || 'Sin nombre' }}</td><td>{{ usuario.celular }}</td><td>{{ usuario.rol }}</td><td>{{ usuario.estado }}</td><td><button v-if="usuario.estado === 'activo' && usuario.rol === 'cliente'" class="btn btn-sm btn-outline-warning me-1" type="button" @click="accion(usuario.idUsuario,'suspender')">Suspender</button><button v-if="usuario.estado === 'suspendido'" class="btn btn-sm btn-outline-success" type="button" @click="accion(usuario.idUsuario,'levantar-suspension')">Levantar</button><button v-if="usuario.estado !== 'baneado' && usuario.rol === 'cliente'" class="btn btn-sm btn-outline-danger ms-1" type="button" @click="accion(usuario.idUsuario,'banear')">Banear</button></td></tr></tbody></table></div></section></template>
